def min_coins(coins, amount):
    INF = amount + 1
    dp = []
    for a in range(amount + 1):
        dp.append(INF)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    if dp[amount] > amount:
        return -1
    return dp[amount]


def main():
    coins = list(map(int, input().split()))
    amount = int(input())
    print(min_coins(coins, amount))


main()

def max_loot(cash):
    n = len(cash)
    dp = []
    for i in range(n):
        dp.append(0)
    dp[0] = cash[0]
    if n > 1:
        dp[1] = cash[0] if cash[0] > cash[1] else cash[1]
        for i in range(2, n):
            best = cash[i] + dp[i - 2]
            if dp[i - 1] > best:
                best = dp[i - 1]
            dp[i] = best
    return dp[n - 1]


def main():
    cash = list(map(int, input().split()))
    print(max_loot(cash))


main()

from functools import lru_cache


@lru_cache(maxsize=None)
def steps_to_one(n):
    if n == 1:
        return 0
    best = steps_to_one(n - 1)
    if n % 2 == 0:
        two = steps_to_one(n // 2)
        if two < best:
            best = two
    if n % 3 == 0:
        three = steps_to_one(n // 3)
        if three < best:
            best = three
    return best + 1


def main():
    n = int(input())
    print(steps_to_one(n))


main()

def lcs_length(a, b):
    n = len(a)
    m = len(b)
    dp = []
    for i in range(n + 1):
        dp.append([0] * (m + 1))
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = dp[i - 1][j] if dp[i - 1][j] > dp[i][j - 1] else dp[i][j - 1]
    return dp[n][m]


def main():
    a = input().strip()
    b = input().strip()
    print(lcs_length(a, b))


main()

def subset_sum(nums, target):
    dp = []
    for t in range(target + 1):
        dp.append(False)
    dp[0] = True
    for x in nums:
        for t in range(target, x - 1, -1):
            if dp[t - x]:
                dp[t] = True
    return dp[target]


def main():
    nums = list(map(int, input().split()))
    target = int(input())
    print(subset_sum(nums, target))


main()

def min_paint_cost(costs):
    r = 0
    g = 0
    b = 0
    for row in costs:
        r, g, b = row[0] + min(g, b), row[1] + min(r, b), row[2] + min(r, g)
    return min(r, g, b)


def main():
    first = input().split()
    n = int(first[0])
    vals = []
    while len(vals) < 3 * n:
        vals.extend(input().split())
    costs = []
    for i in range(n):
        costs.append([int(vals[3 * i]), int(vals[3 * i + 1]), int(vals[3 * i + 2])])
    print(min_paint_cost(costs))


main()

def knapsack(weights, values, W):
    dp = []
    for w in range(W + 1):
        dp.append(0)
    for i in range(len(weights)):
        for w in range(W, weights[i] - 1, -1):
            cand = dp[w - weights[i]] + values[i]
            if cand > dp[w]:
                dp[w] = cand
    return dp[W]


def main():
    weights = list(map(int, input().split()))
    values = list(map(int, input().split()))
    W = int(input())
    print(knapsack(weights, values, W))


main()

def lis_length(nums):
    n = len(nums)
    dp = []
    for i in range(n):
        dp.append(1)
    best = 0
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
        if dp[i] > best:
            best = dp[i]
    return best


def main():
    nums = list(map(int, input().split()))
    print(lis_length(nums))


main()

def unique_paths(R, C):
    dp = []
    for _ in range(R):
        dp.append([1] * C)
    for r in range(1, R):
        for c in range(1, C):
            dp[r][c] = dp[r - 1][c] + dp[r][c - 1]
    return dp[R - 1][C - 1]


def main():
    R, C = map(int, input().split())
    print(unique_paths(R, C))


main()

def min_path_sum(grid, R, C):
    dp = []
    for r in range(R):
        dp.append([0] * C)
    dp[0][0] = grid[0][0]
    for c in range(1, C):
        dp[0][c] = dp[0][c - 1] + grid[0][c]
    for r in range(1, R):
        dp[r][0] = dp[r - 1][0] + grid[r][0]
    for r in range(1, R):
        for c in range(1, C):
            dp[r][c] = grid[r][c] + min(dp[r - 1][c], dp[r][c - 1])
    return dp[R - 1][C - 1]


def main():
    R, C = map(int, input().split())
    vals = []
    while len(vals) < R * C:
        vals.extend(input().split())
    grid = []
    for r in range(R):
        grid.append([int(vals[r * C + c]) for c in range(C)])
    print(min_path_sum(grid, R, C))


main()
